// ============================================================
// Nodo: Gestionar Historial
// Acciones: listar | obtener | registrar | borrar | borrar_todo
// Cada usuario (uid = hash de su cuenta de Moodle) tiene su propia
// carpeta; una conversacion = un archivo JSON.
// ============================================================

const fs = require('fs');
const path = require('path');

const RAIZ = '/home/node/.n8n/historial';
const MAX_MENSAJES = 200;
const MAX_TEXTO = 4000;

const body = $input.first().json.body || {};
const accion = String(body.accion || '');
const uid = String(body.uid || '');
const convId = String(body.convId || '');

const uidOk = /^[a-f0-9]{32}$/.test(uid);
const convOk = /^c_[a-z0-9_]{6,60}$/.test(convId);
if (!uidOk) return [{ json: { ok: false, error: 'uid_invalido' } }];

const dir = path.join(RAIZ, uid);
const leer = (f) => { try { return JSON.parse(fs.readFileSync(f, 'utf-8')); } catch (e) { return null; } };

if (accion === 'listar') {
  if (!fs.existsSync(dir)) return [{ json: { ok: true, conversaciones: [] } }];
  const items = fs.readdirSync(dir)
    .filter(f => f.endsWith('.json'))
    .map(f => leer(path.join(dir, f)))
    .filter(c => c && Array.isArray(c.mensajes) && c.mensajes.length > 0)
    .map(c => ({
      convId: c.convId,
      titulo: c.titulo || '(sin titulo)',
      actualizada: c.updated_at,
      mensajes: c.mensajes.length
    }))
    .sort((a, b) => String(b.actualizada).localeCompare(String(a.actualizada)));
  return [{ json: { ok: true, conversaciones: items } }];
}

if (accion === 'obtener') {
  if (!convOk) return [{ json: { ok: false, error: 'conversacion_invalida' } }];
  const c = leer(path.join(dir, `${convId}.json`));
  if (!c) return [{ json: { ok: false, error: 'no_encontrada' } }];
  return [{ json: {
    ok: true,
    convId: c.convId,
    titulo: c.titulo,
    mensajes: c.mensajes.map(m => ({ rol: m.rol, texto: m.texto, ts: m.ts }))
  } }];
}

if (accion === 'registrar') {
  // Guarda intercambios resueltos por el widget sin invocar al modelo
  // (saludos y preguntas factuales), para que aparezcan en el historial.
  if (!convOk) return [{ json: { ok: false, error: 'conversacion_invalida' } }];
  const nuevos = Array.isArray(body.mensajes) ? body.mensajes.slice(0, 4) : [];
  const validos = nuevos.filter(m => m && (m.rol === 'user' || m.rol === 'assistant') && typeof m.texto === 'string');
  if (validos.length === 0) return [{ json: { ok: false, error: 'sin_mensajes' } }];

  fs.mkdirSync(dir, { recursive: true });
  const archivo = path.join(dir, `${convId}.json`);
  const ahora = new Date().toISOString();
  let c = leer(archivo) || { convId, userId: uid, titulo: '', created_at: ahora, updated_at: ahora, mensajes: [] };
  validos.forEach(m => c.mensajes.push({ rol: m.rol, texto: m.texto.substring(0, MAX_TEXTO), ts: ahora }));
  if (c.mensajes.length > MAX_MENSAJES) c.mensajes = c.mensajes.slice(-MAX_MENSAJES);
  if (!c.titulo) {
    const primero = c.mensajes.find(m => m.rol === 'user');
    c.titulo = primero ? String(primero.texto).substring(0, 60) : '';
  }
  c.updated_at = ahora;
  fs.writeFileSync(archivo, JSON.stringify(c, null, 2), 'utf-8');
  return [{ json: { ok: true } }];
}

if (accion === 'borrar') {
  if (!convOk) return [{ json: { ok: false, error: 'conversacion_invalida' } }];
  const archivo = path.join(dir, `${convId}.json`);
  if (fs.existsSync(archivo)) fs.unlinkSync(archivo);
  if (fs.existsSync(dir) && fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
  return [{ json: { ok: true } }];
}

if (accion === 'borrar_todo') {
  let borradas = 0;
  if (fs.existsSync(dir)) {
    fs.readdirSync(dir).filter(f => f.endsWith('.json')).forEach(f => { fs.unlinkSync(path.join(dir, f)); borradas++; });
    if (fs.readdirSync(dir).length === 0) fs.rmdirSync(dir);
  }
  return [{ json: { ok: true, borradas } }];
}

return [{ json: { ok: false, error: 'accion_desconocida' } }];
